typedef struct {
    unsigned short w, h;
    const unsigned char (*regs)[2];
    unsigned n;
    const char *name;
} ov2640_size_t;

#define OV2640_SZ(w, h, t, n) { w, h, t, sizeof(t) / 2, n }
static const ov2640_size_t ov2640_sizes[] = {
    OV2640_SZ(176,  144,  ov2640_size_qcif, "QCIF"),
    OV2640_SZ(320,  240,  ov2640_size_qvga, "QVGA"),
    OV2640_SZ(352,  288,  ov2640_size_cif,  "CIF"),
    OV2640_SZ(640,  480,  ov2640_size_vga,  "VGA"),
    OV2640_SZ(800,  600,  ov2640_size_svga, "SVGA"),
    OV2640_SZ(1024, 768,  ov2640_size_xga,  "XGA"),
    OV2640_SZ(1280, 1024, ov2640_size_sxga, "SXGA"),
    OV2640_SZ(1600, 1200, ov2640_size_uxga, "UXGA"),
};
#define OV2640_NUM_SIZES (sizeof(ov2640_sizes) / sizeof(ov2640_sizes[0]))

